-- Kenya ADM1 counties (47) from OCHA COD-AB.
-- Source: https://data.humdata.org/dataset/cod-ab-ken
-- Resource: ken_admin_boundaries.geojson.zip / ken_admin1.geojson
-- Generated: 2026-11-16. GIDs are assigned 1-47 by adm1_pcode and are stable
-- for this seed; the app treats them as opaque county identifiers.
BEGIN;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM kenya_counties) THEN
    RAISE EXCEPTION 'kenya_counties is not empty; run this seed only on a fresh database';
  END IF;
END $$;
;
COMMIT;
